// const serve = require('rollup-plugin-serve');
const { nodeResolve } = require("@rollup/plugin-node-resolve");
const { wasm } = require("./build/wasm-plugin.cjs");
const liveReload = require("rollup-plugin-livereload");
const commonJs = require("@rollup/plugin-commonjs");
const nodePolyfills = require("rollup-plugin-polyfill-node");
const typescript = require("@rollup/plugin-typescript");
const json = require("@rollup/plugin-json");
const replace = require("@rollup/plugin-replace");
const path = require("path");
const copy = require("rollup-plugin-copy");
const dev = require("rollup-plugin-dev");
const authHeader = (originalReq, headers) => ({
  ...headers,
  Authorization: `Basic ${Buffer.from("admin:admin").toString("base64")}`,
});
/**
 * @type {import('rollup').RollupOptions}
 */
module.exports = [
  {
    input: "src/example/parent.ts",
    output: {
      dir: "dist/browser",
      format: "iife",
    },
    plugins: [
      // serve('dist/browser'),
      dev({
        dirs: ["dist/browser"],
        port: 10001,
        proxy: [
          {
            from: "/uxasset/externals",
            to: "http://localhost:8080/uxasset/externals",
            opts: {
              rewriteRequestHeaders: authHeader,
            },
          },
          {
            from: "/api",
            to: "http://localhost:8080/api",
            opts: {
              rewriteRequestHeaders: authHeader,
            },
          },
          {
            from: "/amb",
            to: "http://localhost:8080/amb",
            opts: {
              rewriteRequestHeaders: authHeader,
              websocket: true,
            },
          },
        ],
      }),
      liveReload(),
      typescript({
        tsconfig: "./tsconfig.test.json",
      }),
    ],
  },
  {
    input: "src/example/bundler.ts",
    output: {
      dir: "dist/browser",
      format: "iife",
      sourcemap: true,
      // Needed for resolving issue with wasm loader in rollup
      intro: `const document = {currentScript: {src: globalThis.location.href, tagName: 'script'}, baseURI: globalThis.location.origin};`,
    },
    plugins: [
      commonJs(),
      nodeResolve(),
      wasm(),
      typescript({
        tsconfig: "./tsconfig.test.json",
      }),
      json(),
      replace({
        preventAssignment: true,
        "process.versions.node": JSON.stringify(process.versions.node),
      }),
      {
        name: "path-polyfill",
        resolveId(importee) {
          if (importee === "path" || importee === "node:path") {
            return require.resolve("./src/path-polyfill.js");
            // Hack to allow importing modules not in package.json#exports
          } else if (
            importee.startsWith("@cyclonedx/cyclonedx-library/") &&
            importee.endsWith(".js")
          ) {
            const pkgRoot = path.dirname(
              require.resolve("@cyclonedx/cyclonedx-library/package.json"),
            );
            const fileToLoad = importee.replace(
              "@cyclonedx/cyclonedx-library/",
              "",
            );
            return path.join(pkgRoot, fileToLoad);
          }
        },
      },
      {
        name: "fs-scurry",
        resolveId(importee) {
          if (
            importee === "fs" ||
            importee === "node:fs" ||
            importee === "node:fs/promises" ||
            importee === "node:url"
          ) {
            return require.resolve("./src/fs-scurry.js");
          }
        },
      },
      {
        name: "minipass",
        resolveId(importee) {
          if (importee === "minipass") {
            return require.resolve("./src/minipass.js");
          }
        },
      },
      nodePolyfills(),
      copy({
        targets: [
          {
            src: require.resolve("@rollup/browser/dist/bindings_wasm_bg.wasm"),
            dest: "dist/browser",
          },
        ],
      }),
    ],
  },
  {
    input: "src/example/orogene/index.ts",
    output: {
      dir: "dist/browser",
      format: "iife",
      sourcemap: true,
    },
    plugins: [
      liveReload(),
      commonJs(),
      nodeResolve(),
      wasm(),
      typescript({
        tsconfig: "./tsconfig.test.json",
      }),
      json(),
      replace({
        preventAssignment: true,
        "process.versions.node": JSON.stringify(process.versions.node),
      }),
      // The path polyfill that comes from rollup-plugin-polyfill-node is incomplete
      {
        name: "path-polyfill",
        resolveId(importee) {
          if (importee === "path") {
            return require.resolve("./src/path-polyfill.js");
          }
          return undefined;
        },
      },
      nodePolyfills(),
    ],
  },
];
